class Solution {
public:
    int makeArrayIncreasing(std::vector<int>& arr1, std::vector<int>& arr2) {
        std::sort(arr2.begin(), arr2.end());
        arr2.erase(std::unique(arr2.begin(), arr2.end()), arr2.end());

        std::unordered_map<int, int> dp;
        dp[-1] = 0;

        for (int x : arr1) {
            std::unordered_map<int, int> nxt;
            for (auto const& [val, ops] : dp) {
                if (x > val) {
                    if (nxt.find(x) == nxt.end() || ops < nxt[x]) nxt[x] = ops;
                }
                auto it = std::upper_bound(arr2.begin(), arr2.end(), val);
                if (it != arr2.end()) {
                    int rep = *it;
                    if (nxt.find(rep) == nxt.end() || ops + 1 < nxt[rep]) nxt[rep] = ops + 1;
                }
            }
            dp = std::move(nxt);
            if (dp.empty()) return -1;
        }

        int ans = 1e9;
        for (auto const& [val, ops] : dp) ans = std::min(ans, ops);
        return ans == 1e9 ? -1 : ans;
    }
};

class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        java.util.TreeSet<Integer> set = new java.util.TreeSet<>();
        for (int x : arr2) set.add(x);

        java.util.Map<Integer, Integer> dp = new java.util.HashMap<>();
        dp.put(-1, 0);

        for (int x : arr1) {
            java.util.Map<Integer, Integer> nxt = new java.util.HashMap<>();
            for (java.util.Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int val = entry.getKey();
                int ops = entry.getValue();

                if (x > val) {
                    nxt.put(x, Math.min(nxt.getOrDefault(x, Integer.MAX_VALUE), ops));
                }
                Integer rep = set.higher(val);
                if (rep != null) {
                    nxt.put(rep, Math.min(nxt.getOrDefault(rep, Integer.MAX_VALUE), ops + 1));
                }
            }
            dp = nxt;
            if (dp.isEmpty()) return -1;
        }

        int ans = Integer.MAX_VALUE;
        for (int ops : dp.values()) ans = Math.min(ans, ops);
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

var makeArrayIncreasing = function(arr1, arr2) {
    const sorted2 = Array.from(new Set(arr2)).sort((a, b) => a - b);
    let dp = new Map([[-1, 0]]);

    const bisectRight = (arr, target) => {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    };

    for (const x of arr1) {
        const nxt = new Map();
        for (const [val, ops] of dp.entries()) {
            if (x > val) {
                const prev = nxt.get(x) ?? Infinity;
                if (ops < prev) nxt.set(x, ops);
            }
            const idx = bisectRight(sorted2, val);
            if (idx < sorted2.length) {
                const rep = sorted2[idx];
                const prev = nxt.get(rep) ?? Infinity;
                if (ops + 1 < prev) nxt.set(rep, ops + 1);
            }
        }
        dp = nxt;
        if (dp.size === 0) return -1;
    }

    let ans = Infinity;
    for (const ops of dp.values()) ans = Math.min(ans, ops);
    return ans === Infinity ? -1 : ans;
};
